  FT["PH-H4284"] = {"id":"PH-H4284","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5485_1969.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"增加邦阿西楠省助理省检察官人数，并为此修订《行政法典》第1674条（经修正）的法案","en":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Pangasinan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","orig":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Pangasinan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 5485","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5485_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4284-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The provision of Section sixteen hundred seventy-four of the Revised Administrative Code, as amended, relative to the number of assistant provincial fiscals in the Province of Pangasinan, is further amended to read as follows:\n\"Pangasinan, twenty-six assistant provincial fiscals;\""}},{"id":"PH-H4284-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p60","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Number of Assistant Provincial Fiscals for the Province of Pangasinan, Amending for the Purpose Section Sixteen Hundred Seventy-Four of the Administrative Code, as Amended","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H4285"] = {"id":"PH-H4285","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1969/ra_5486_1969.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将南甘马粦省划分为两个公路工程区的法案","en":"An Act Constituting the Province of Camarines Sur Into Two Highway Engineering Districts","orig":"An Act Constituting the Province of Camarines Sur Into Two Highway Engineering Districts"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 5486","issuingBody":"Congress of the Philippines","promulgatedDate":"1969-06-21","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1969/ra_5486_1969.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H4285-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Any provision of law to the contrary notwithstanding, the Province of Camarines Sur shall be constituted into two highway engineering districts. The first engineering district shall comprise the towns within the first congressional district namely, Bombon, Cabusao, Calabanga, Camaligan, Canaman, Del Gallego, Gainza, Libmanan, Lupi, Magarao, Milaor, Minalabac, Pamplona, Pasacao, Ragay, San Fernando and Sipocot. The second engineering district shall comprise towns within the second congressional district, namely Baao, Balatan, Bato, Buhi, Bula, Caramoan, Garchitorena, Goa; Iriga, Lagonoy, Nabua, Ocampo, Pili, Sagnay, San Jose, Siruma, Tigaon arid Tinambac."}},{"id":"PH-H4285-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Each engineering district shall have one District Engineer II and one Administrative Officer II who shall be appointed in accordance with existing laws."}},{"id":"PH-H4285-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The headquarters for the first engineering district shall be at Baras, Canaman and for the second engineering district at Pili."}},{"id":"PH-H4285-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Any provision of law, rule or regulation to the contrary notwithstanding the minimum qualification for the position of District Engineer II as provided in Section two hereof, shall be Supervising Civil Engineer I."}},{"id":"PH-H4285-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, June 21, 1969."}}],"pack":"ph-p60","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the Province of Camarines Sur Into Two Highway Engineering Districts","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
